window.FILM_WORK_PROMPTS={"work_id":"src-4e3a7dbea4f80b28","records":[{"work_id":"src-4e3a7dbea4f80b28","frame_id":"FG-8a197b38f657fb49","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/15 (781).jpg","source_page":"https://film-grab.com/2012/09/13/observe-and-report/","scene":"室内办公环境，一名穿深色西装的男子与一名金发女子面对面坐着交谈，背景有两名穿蓝色制服的警员，一人站立一人坐着，墙上挂有黑白照片。","analysis":"画面采用平视角度，前景人物占据主要视觉空间，西装男子位于左侧，金发女子位于右侧，两人均可见上半身。背景警员身形较小，形成景深对比。室内光线柔和，色调偏冷，蓝色制服与深色西装形成色彩对比，台灯提供局部暖色光源，整体光影层次分明。","prompt":"室内场景，左侧一名棕色短发男子身穿深色西装白衬衫蓝领带，身体前倾面向右侧；右侧一名金色马尾女子身穿黑色深V上衣，佩戴黑色圆环耳环，侧身面向左侧；背景左侧站立一名穿蓝色短袖制服黑领带警员，中间坐着一名穿蓝色长袖制服黑领带警员；墙面挂有两幅黑白照片，右侧有一盏米色灯罩台灯，整体色调偏冷，室内光线柔和，人物面部有自然阴影。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:41:38-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/15 (781).jpg","observed_dimensions":[1024,427],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.49,"observed_resolution":"normal","observation_limits":[],"id":"VP-eaaf22b8ee4bdfb7","origin":"visual"},{"work_id":"src-4e3a7dbea4f80b28","frame_id":"FG-59894d34530c1c7b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/26 (781).jpg","source_page":"https://film-grab.com/2012/09/13/observe-and-report/","scene":"一名身穿蓝色制服的短发男子位于画面中央，背景是昏暗的办公室，可见模糊的办公桌、文件架和电脑屏幕。","analysis":"人物上半身及头部占据画面中心主要位置，面部清晰，背景环境虚化。光线从上方投射，照亮人物面部，背景较暗，形成明暗对比。蓝色制服与深色背景形成色彩反差，整体色调偏冷。","prompt":"一名身穿蓝色制服衬衫的短发男子，面部正对镜头，神情严肃，占据画面中心。背景是昏暗的办公室环境，可见模糊的木质办公桌、堆叠的文件架、电脑显示器以及墙上的纸张。光线从上方投射，照亮人物面部，背景处于阴影中，整体色调偏冷，蓝色制服与深色背景形成对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:41:44-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/26 (781).jpg","observed_dimensions":[1024,427],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.522,"observed_resolution":"normal","observation_limits":[],"id":"VP-34d8085ac372f49a","origin":"visual"},{"work_id":"src-4e3a7dbea4f80b28","frame_id":"FG-eecb247cfcca67bb","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/38 (777).jpg","source_page":"https://film-grab.com/2012/09/13/observe-and-report/","scene":"一名身穿米色西装、内搭深红衬衫并系着蓝红条纹领带的男子站在室内。他身后是深青色的墙壁，墙上挂着一份镶框的证书和一块木质浮雕牌匾，右侧是一个深色的门洞。","analysis":"画面主体为男子的上半身，其身体右侧（画面右侧）被裁切。人物位于画面右半部分，左侧墙面占据约三分之一空间，墙上挂有证书和浮雕。光线从画面左侧照入，在人物面部和西装上形成明暗对比，背景门洞处于阴影中。整体色调偏冷，以青色墙面和米色衣物为主。","prompt":"一名留着短发和八字胡的男子站在室内，身穿米色西装外套，内搭深红色衬衫，系着蓝红相间的斜条纹领带。他身体微侧，目光看向画面左侧。背景是深青色的墙壁，左侧挂着一份带有蓝色边框的证书，中间有一块深褐色的木质浮雕牌匾。画面右侧是一个深黑色的门洞，光线从左侧照射，在人物面部和衣物上形成柔和的明暗过渡，整体氛围冷静。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:41:51-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/38 (777).jpg","observed_dimensions":[1024,427],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.475,"observed_resolution":"normal","observation_limits":[],"id":"VP-472a6fa732defed2","origin":"visual"},{"work_id":"src-4e3a7dbea4f80b28","frame_id":"FG-1974a180e6bcba89","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/5 (16).jpg","source_page":"https://film-grab.com/2012/09/13/observe-and-report/","scene":"停车场内，一名身穿长款大衣的人物背对镜头，双手向两侧撑开大衣下摆，呈奔跑姿态。周围停放着多辆轿车，远处有树木和建筑，地面有长投影。","analysis":"画面采用低角度仰拍，主体人物位于画面中央偏左，全身可见，占据画面约三分之一高度。人物双手撑开大衣，形成宽大的轮廓。背景为停车场，车辆排列整齐，远处有树木和建筑。光线从右侧照射，形成明显的长投影，色彩偏暖，呈现黄昏或清晨的氛围。","prompt":"黄昏时分的露天停车场，一名身穿灰褐色长款大衣的人物背对镜头，双手向两侧撑开大衣下摆，呈奔跑姿态。人物全身可见，位于画面中央偏左，占据画面约三分之一高度。周围停放着多辆轿车，包括银色、红色和深色车辆，排列整齐。远处有树木和建筑，地面有长投影。光线从右侧照射，形成明显的长投影，色彩偏暖，呈现黄昏或清晨的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:41:59-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/5 (16).jpg","observed_dimensions":[1024,427],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.541,"observed_resolution":"normal","observation_limits":[],"id":"VP-5095f7b013de6f69","origin":"visual"},{"work_id":"src-4e3a7dbea4f80b28","frame_id":"FG-ae1978f54d54bb2c","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (682).jpg","source_page":"https://film-grab.com/2012/09/13/observe-and-report/","scene":"快餐店柜台前，一名穿粉色上衣红围裙的女子与一名穿蓝灰卫衣的男子相对而坐，两人均低头注视桌面，背景可见模糊的柜台与站立人影。","analysis":"画面采用平视视角，前景两人占据画面主要位置，呈左右对称布局。人物上半身及大腿部分清晰可见，面部表情因低头而显得内敛。背景柜台及站立人物处于焦外虚化状态，形成景深对比。光线柔和均匀，暖色调的室内照明与冷色调的衣物形成色彩层次，整体氛围安静且略带压抑感。","prompt":"快餐店室内场景，前景一张白色方形小桌，左侧坐着一名红发女子，身穿粉色长袖上衣系红色围裙，身体前倾低头；右侧坐着一名短发男子，身穿蓝灰色连帽卫衣，同样低头注视桌面。两人之间放着一个白色纸杯和调味瓶。背景是模糊的快餐柜台，可见玻璃展示柜、食物亮区以及几名站立或行走的模糊人影。画面色调偏暖，光线柔和，景深较浅，焦点集中在前景人物身上，营造出一种安静、私密的对话氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:42:06-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (682).jpg","observed_dimensions":[1024,427],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.527,"observed_resolution":"normal","observation_limits":[],"id":"VP-2c590c71a726faad","origin":"visual"},{"work_id":"src-4e3a7dbea4f80b28","frame_id":"FG-12435441c8754295","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/14 (781).jpg","source_page":"https://film-grab.com/2012/09/13/observe-and-report/","scene":"金发女子坐在汽车驾驶座上，右手握着方向盘，身体侧向镜头。车窗外可见明亮的街道、树木和停放的车辆，车内后视镜上挂着彩色装饰物。","analysis":"画面采用侧面视角，人物占据画面右侧约二分之一区域，呈现上半身及手臂。光线从左侧车窗射入，照亮人物面部和手臂，形成明显的明暗对比。背景街道处于虚焦状态，色彩明亮，与车内较暗的色调形成反差。","prompt":"一位金发马尾女子坐在汽车驾驶座，身穿黑色上衣，佩戴银色耳环，右手握住黑色方向盘，身体侧向镜头，神情专注。车内后视镜上挂着一串彩色花朵装饰。车窗外是明亮的日间街道，可见绿树、灰色建筑及远处停放的车辆。自然光从左侧车窗射入，照亮人物面部和手臂，车内阴影较重，背景街道略微虚化，色彩对比鲜明。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T01:47:11+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/14 (781).jpg","observed_dimensions":[1024,427],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.471,"observed_resolution":"normal","observation_limits":[],"id":"VP-e4415cc4365240f8","origin":"visual"},{"work_id":"src-4e3a7dbea4f80b28","frame_id":"FG-bb1feb7da5ca06a1","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/27 (781).jpg","source_page":"https://film-grab.com/2012/09/13/observe-and-report/","scene":"俯视视角下，两名身穿白色上衣的人物位于沙土场地中的金属铁丝网笼内，一人站立，一人俯身，地面投射出清晰的长影。","analysis":"画面采用高角度俯视构图，主体为占据画面中央的矩形铁丝网围栏结构。两名人物全身可见，体型在广阔沙地中显得较小。强烈的直射光从上方投射，使人物和围栏在黄褐色沙地上形成深黑色长影，光影对比强烈，色调统一为暖黄与深褐。","prompt":"高角度俯视镜头，展现一片干燥的黄褐色沙土场地。画面中央矗立着由金属立柱和铁丝网构成的矩形围栏结构，围栏内部空间清晰可见。两名身穿白色短袖上衣和深色短裤的人物位于围栏内，一人站立，一人俯身，姿态自然。强烈的阳光从上方直射，在粗糙的沙地上投射出人物和围栏的深黑色长影，光影对比鲜明。整体色调呈现暖黄与深褐的质感，画面具有强烈的几何线条感和空间纵深感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T01:47:19+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/27 (781).jpg","observed_dimensions":[1024,427],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.553,"observed_resolution":"normal","observation_limits":[],"id":"VP-51c6583813ab9ffc","origin":"visual"},{"work_id":"src-4e3a7dbea4f80b28","frame_id":"FG-dfb584b97adaf442","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/39 (777).jpg","source_page":"https://film-grab.com/2012/09/13/observe-and-report/","scene":"一名身穿蓝色制服的男子站在狭窄走廊尽头，左侧前景有白色柜体和堆叠的麻袋，右侧为大面积白色瓷砖墙面。","analysis":"画面采用纵深构图，走廊线条将视线引向中心人物。人物全身可见，位于画面中后景，因距离显得较小。左侧前景物体占据约三分之一画面，右侧墙面占据约二分之一。光线从左侧射入，在金属墙面形成高光，整体色调偏冷，明暗对比集中在左侧亮区与走廊深处的阴影中。","prompt":"写实风格室内场景，狭窄的走廊空间。画面左侧前景放置着一台白色立式柜体，旁边堆叠着两个米色麻袋，后方是反光的金属墙面，上方有红色瓷砖装饰带。画面右侧是大面积白色瓷砖墙壁，延伸至远处。走廊尽头站着一名身穿蓝色长袖制服、深色长裤的男子，全身可见，正面向镜头站立。背景深处有一扇开启的门，透出淡蓝色光线。整体光线偏冷，左侧受光较强，走廊内部较暗，呈现出一种压抑、冷峻的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T01:47:26+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/39 (777).jpg","observed_dimensions":[1024,427],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.518,"observed_resolution":"normal","observation_limits":[],"id":"VP-8b8cd237750c9e50","origin":"visual"},{"work_id":"src-4e3a7dbea4f80b28","frame_id":"FG-026841510441c3f0","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/49 (751).jpg","source_page":"https://film-grab.com/2012/09/13/observe-and-report/","scene":"夜间街道，一辆敞篷跑车停在路中。车内驾驶位坐着一名穿浅蓝上衣的人物，正抬起右臂伸向挡风玻璃上方。背景是模糊的店铺灯光和街道建筑。","analysis":"画面采用车内后座视角，前景为两个深色座椅头枕，占据画面下方约三分之一。中景为驾驶位人物，仅可见上半身及抬起的右臂，头部被阴影笼罩。背景街道虚化，红色后视镜与蓝色仪表盘形成色彩对比。整体光线昏暗，主要光源来自背景街道的暖色灯光及车内仪表盘的冷色光，营造出夜间静谧氛围。","prompt":"夜间城市街道，从敞篷跑车后座视角拍摄。前景是两个深灰色座椅头枕，占据画面底部。中景驾驶位坐着一名穿浅蓝色短袖上衣的人物，黑色卷发，右臂向上抬起伸向挡风玻璃顶部，身体略微前倾。车内可见银色中控台、蓝色发光的仪表盘和红色后视镜。背景是虚化的街道，远处有模糊的红色和白色灯光，路面呈深灰色。整体色调偏暗，冷暖光交织，景深较浅，焦点集中在车内人物与座椅上。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T01:47:34+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/49 (751).jpg","observed_dimensions":[1024,427],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.449,"observed_resolution":"normal","observation_limits":[],"id":"VP-b2b75122cd216d70","origin":"visual"},{"work_id":"src-4e3a7dbea4f80b28","frame_id":"FG-47771b03c3cc17fb","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/61 (659).jpg","source_page":"https://film-grab.com/2012/09/13/observe-and-report/","scene":"画面为极近距离的人脸局部特写，可见两名人物面部紧贴，左侧人物脸颊与右侧人物鼻唇部接触，背景为模糊的暖色块，无其他环境细节。","analysis":"构图极度紧凑，几乎填满整个画幅，仅保留极少背景空间。人物身体仅可见面部下半部分，包括鼻子、嘴唇、下巴及脸颊皮肤纹理。视角为平视，光线柔和偏暖，皮肤呈现自然的肉色与阴影过渡，右侧人物面部处于较暗的阴影中，左侧受光稍多，明暗对比集中在鼻翼与嘴唇接触处。","prompt":"极近距离的人脸局部特写，画面被两张紧贴的面孔填满，左侧人物露出脸颊、下巴及部分金发，右侧人物露出鼻子、嘴唇和下巴，两人的面部皮肤纹理清晰可见，毛孔与细微瑕疵真实呈现。右侧人物鼻翼与左侧人物脸颊紧密接触，嘴唇微张。背景为模糊的暖黄色与暗色块，光线柔和偏暖，从左侧照射，在右侧人物面部形成阴影，整体色调为自然的肤色与暗部对比，无其他物体或环境细节。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T01:47:41+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/61 (659).jpg","observed_dimensions":[1024,427],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.513,"observed_resolution":"normal","observation_limits":[],"id":"VP-f120859fded39851","origin":"visual"}]};